UPDATE HC_MALL.T_HAPPYCON_COUPON_HST A
   SET A.RCV_PHONE = (CASE WHEN LENGTH(A.RCV_PHONE) <= 30 THEN (CASE WHEN TRIM(REPLACE(A.RCV_PHONE,'-','')) IS NOT NULL THEN RAWTOHEX(STANDARD_HASH(REPLACE(A.RCV_PHONE,'-',''),'SHA256')) ELSE ' ' END) ELSE A.RCV_PHONE END)
 WHERE A.ORDER_NO = #{orderNo}
